output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are not allowed in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartInSingleFileAisle": {
          "and": [
            "hasCart",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileAisle"
    }
  },
  {
    "id": "no_cart_entry_single_file",
    "text": "An agent must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_before_north_entry",
    "text": "At the mouth of a pedestrian-only shelf aisle, the agent may not move north into the aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartAtPedestrianAisleMouth": {
          "and": [
            "hasCart",
            "pedestrianAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAtPedestrianAisleMouth",
          "N"
        ]
      }
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "Whenever the agent parks a cart at a pedestrian-aisle mouth, the agent is obliged to retrieve a cart again before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "releaseCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "pedestrianAisleMouth",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "releaseCartAtMouth",
      "discharge": "recoverCart"
    }
  },
  {
    "id": "cartless_only_in_foot_zones",
    "text": "After leaving the entrance/cart-bay area, an agent without a cart should only be in the pedestrian shelf aisle or its cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entryCartBayZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "allowedCartlessZone": {
          "or": [
            "singleFileShelfAisle",
            "pedestrianAisleMouth",
            "entryCartBayZone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessZone"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_needs_cart",
    "text": "Shelf interactions in wide cart-accessible aisles must be performed while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideCartAccessibleShelf": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideCartAccessibleShelf",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "foot_aisle_visit_requires_service",
    "text": "Entering a single-file shelf aisle on foot creates an obligation to interact with a shelf in that aisle before finishing.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "onFootInSingleFileAisle": {
          "and": [
            {
              "not": "hasCart"
            },
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "onFootInSingleFileAisle"
        },
        "onFootShelfInteractionInSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "onFootShelfInteractionInSingleFileAisle"
    }
  },
  {
    "id": "drop_cart_only_at_mouth",
    "text": "Carts may only be released at designated pedestrian-aisle mouths, not elsewhere in the store.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "releaseCartAwayFromMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "pedestrianAisleMouth"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "releaseCartAwayFromMouth"
    }
  }
]
